typedef unsigned char B;typedef struct{B*x,*v;size_t n;}P;static size_t Q(unsigned d){size_t n=1;while(d--)n*=3;return n;}static void T(const B*k,uint64_t p,unsigned l,const B*x,B*t){B m[28]={0x50,0x33,0x57,(B)l},z[32];unsigned n;for(int i=0;i<8;i++)m[11-i]=(B)(p>>(8*i));memcpy(m+12,x,16);HMAC(EVP_sha256(),k,32,m,28,z,&n);memcpy(t,z,16);}static void E(const B*x,unsigned d,uint64_t p,unsigned l,const B*k,P*r,size_t*i){if(!d){memcpy(r->x+16*(*i),x,16);r->v[(*i)++]=1;return;}B t[16],c[16];T(k,p,l,x,t);for(int j=0;j<16;j++)c[j]=x[j]^t[j];E(x,d-1,p*3,l+1,k,r,i);E(t,d-1,p*3+1,l+1,k,r,i);E(c,d-1,p*3+2,l+1,k,r,i);}static int C(const B*k,uint64_t p,unsigned l,const B*a,const B*b,int q,B*x){B t[16],h[16];if(!q){memcpy(x,a,16);memcpy(t,b,16);}else if(q==1){memcpy(x,a,16);for(int i=0;i<16;i++)t[i]=a[i]^b[i];}else{memcpy(t,a,16);for(int i=0;i<16;i++)x[i]=a[i]^b[i];}T(k,p,l,x,h);return!CRYPTO_memcmp(t,h,16);}static int D(P*r,size_t o,unsigned d,uint64_t p,unsigned l,const B*k,B*x){if(!d){if(!r->v[o])return 0;memcpy(x,r->x+16*o,16);return 1;}size_t s=Q(d-1);B y[3][16],c[16];int v[3],h=0;for(int j=0;j<3;j++)v[j]=D(r,o+j*s,d-1,p*3+j,l+1,k,y[j]);for(int a=0;a<3;a++)for(int b=a+1;b<3;b++)if(v[a]&&v[b]&&C(k,p,l,y[a],y[b],a?2:b-1,c)){if(h&&memcmp(x,c,16))return 0;memcpy(x,c,16);h=1;}return h;}P p3e(const B x[16],unsigned d,const B k[32]){P r={0};r.n=Q(d);r.x=malloc(16*r.n);r.v=calloc(r.n,1);size_t i=0;E(x,d,0,0,k,&r,&i);return r;}int p3d(P*r,unsigned d,const B k[32],B x[16]){return D(r,0,d,0,0,k,x);}void p3f(P*r){free(r->x);free(r->v);*r=(P){0};}
